<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref, watch } from 'vue';
import { ElMessage, ElMessageBox } from 'element-plus';
import { ArrowRight, ArrowDown, Bell, Search, Refresh, Download, TrendCharts, Fold, Expand, Grid, Tickets, User, UserFilled, Service, Document, TopRight, Check, Close, Monitor, CircleCheck, Clock, Switch, CreditCard, Select } from '@element-plus/icons-vue';
import { api, useStaff } from './store';
import { CLUB_NAME, CLUB_NAME_EN, ApiError, canServe, serviceLabels, orderSummary, orderMembers, participantEarnings, money, compactMoney, statusLabels, roleLabels, time, type Application, type Order, type Player, type Game, type Dashboard, type Audit, type ClubSettings, type ClubUser, type Role } from '@stellar/core';
const staff=useStaff();
const nav=[{id:'dashboard',label:'概览看板',icon:Grid},{id:'orders',label:'订单工作台',icon:Tickets},{id:'players',label:'成员管理',icon:UserFilled},{id:'customers',label:'客户管理',icon:User},{id:'refunds',label:'退款售后',icon:Service},{id:'audit',label:'操作日志',icon:Document}];
const legacyPages:Record<string,string>={applications:'customers',settlements:'orders',settings:'dashboard'};
const initialPage=location.hash.slice(1)||'dashboard';
const page=ref(legacyPages[initialPage]||initialPage);
const registeredUsers=ref<ClubUser[]>([]),customerFilter=ref('all'),progressDrawer=ref(false),progressUserId=ref('');
const applicationLabels:Record<Application['status'],string>={pending:'资料待审核',assessment:'专项考核中',approved:'已通过',rejected:'未通过'};
const applications=ref<Application[]>([]);
const applicationDialog=ref(false),selectedApplication=ref<Application|null>(null),applicationAction=ref<'assessment'|'approved'|'rejected'>('assessment'),assessmentScore=ref(80),assessmentNote=ref('');
const serviceFilter=ref('all');
const orders=ref<Order[]>([]),players=ref<Player[]>([]),games=ref<Game[]>([]),dashboard=ref<Dashboard|null>(null),audit=ref<Audit[]>([]),settings=ref<ClubSettings|null>(null);
const loading=ref(true),refreshing=ref(false),busy=ref(false),loadError=ref(''),query=ref(''),globalSearch=ref(''),gameFilter=ref('all'),statusFilter=ref('all'),refundFilter=ref('pending'),playerFilter=ref('all'),currentPage=ref(1),pageSize=8,sidebarCollapsed=ref(false);
const sidebarViewport=window.matchMedia('(max-width: 800px)');
const isCompactViewport=ref(sidebarViewport.matches),mobileSidebarOpen=ref(false);
const sidebarExpanded=computed(()=>isCompactViewport.value?mobileSidebarOpen.value:!sidebarCollapsed.value);
const sidebarToggleLabel=computed(()=>isCompactViewport.value?(mobileSidebarOpen.value?'关闭菜单':'打开菜单'):(sidebarCollapsed.value?'展开侧边栏':'收起侧边栏'));
function toggleSidebar(){if(isCompactViewport.value)mobileSidebarOpen.value=!mobileSidebarOpen.value;else sidebarCollapsed.value=!sidebarCollapsed.value;}
function onSidebarViewportChange(event:MediaQueryListEvent){isCompactViewport.value=event.matches;mobileSidebarOpen.value=false;}
function onSidebarKeydown(event:KeyboardEvent){if(event.key==='Escape'&&mobileSidebarOpen.value){mobileSidebarOpen.value=false;document.querySelector<HTMLButtonElement>('.sidebar-toggle')?.focus();}}
const orderDrawer=ref(false),selectedOrder=ref<Order|null>(null),assignDialog=ref(false),assignPlayer=ref(''),assignReason=ref(''),refundDialog=ref(false),reviewApprove=ref(true),reviewNote=ref(''),playerDialog=ref(false),selectedPlayer=ref<Player|null>(null),editPrice=ref(0),roleDialog=ref(false),customerDrawer=ref(false),customerId=ref('');
let refreshTimer:ReturnType<typeof setInterval>;
const isAdmin=computed(()=>staff.session?.role==='admin');
const canFinance=computed(()=>['admin','finance'].includes(staff.session?.role||''));
const canDispatch=computed(()=>['admin','customer_service'].includes(staff.session?.role||''));
const availableNav=computed(()=>nav.filter(n=>n.id!=='audit'||isAdmin.value));
const pageLabel=computed(()=>nav.find(n=>n.id===page.value)?.label||'概览看板');
const onlinePlayers=computed(()=>players.value.filter(p=>p.approved&&p.available));
const pendingRefunds=computed(()=>orders.value.filter(o=>o.refundStatus==='pending'));
const filteredOrders=computed(()=>orders.value.filter(o=>(statusFilter.value==='all'||o.status===statusFilter.value)&&(serviceFilter.value==='all'||o.serviceType===serviceFilter.value)&&(gameFilter.value==='all'||o.gameId===gameFilter.value)&&[o.id,o.bossName,o.playerName,o.gameName].join(' ').toLowerCase().includes(query.value.trim().toLowerCase())));
const pagedOrders=computed(()=>filteredOrders.value.slice((currentPage.value-1)*pageSize,currentPage.value*pageSize));
const filteredPlayers=computed(()=>players.value.filter(p=>p.approved&&(playerFilter.value==='all'||(playerFilter.value==='online'?p.available:!p.available))&&[p.name,p.subtitle,...p.tags].join(' ').toLowerCase().includes(query.value.toLowerCase())&&(gameFilter.value==='all'||p.gameIds.includes(gameFilter.value))));
const filteredRefunds=computed(()=>orders.value.filter(o=>o.refundStatus!=='none'&&(refundFilter.value==='all'||o.refundStatus===refundFilter.value)&&[o.id,o.bossName,o.playerName].join(' ').includes(query.value)));
const allCustomers=computed(()=>registeredUsers.value.map(user=>{
  const list=orders.value.filter(o=>o.bossId===user.id),profile=players.value.find(p=>p.userId===user.id);
  const history=applications.value.filter(a=>a.userId===user.id).sort((a,b)=>b.createdAt-a.createdAt);
  return {...user,count:list.length,total:list.filter(o=>o.paidAt).reduce((n,o)=>n+o.amount-(o.refundStatus==='refunded'?o.refundAmount||0:0),0),last:list.length?Math.max(...list.map(o=>o.createdAt)):null,active:list.filter(o=>['waiting','accepted','serving','confirming'].includes(o.status)).length,refunds:list.filter(o=>o.refundStatus==='pending').length,qualifications:profile?.approved?profile.qualifications:[],applications:history,onboarding:history.some(a=>['pending','assessment'].includes(a.status))};
}));
const customers=computed(()=>allCustomers.value.filter(c=>[c.name,c.id].join(' ').toLowerCase().includes(query.value.trim().toLowerCase())&&(customerFilter.value==='all'||(customerFilter.value==='onboarding'?c.onboarding:customerFilter.value==='qualified'?c.qualifications.length>0:!c.applications.length&&!c.qualifications.length))));
const selectedCustomer=computed(()=>allCustomers.value.find(c=>c.id===customerId.value));
const customerOrders=computed(()=>orders.value.filter(o=>o.bossId===customerId.value));
const progressUser=computed(()=>allCustomers.value.find(c=>c.id===progressUserId.value));
const pendingApplications=computed(()=>applications.value.filter(a=>['pending','assessment'].includes(a.status)));
function openProgress(userId:string){progressUserId.value=userId;progressDrawer.value=true;}
function settlementLabel(o:Order){if(o.refundStatus==='pending')return '售后暂停结算';if(o.status==='cancelled')return '未产生报酬';if(o.status!=='completed')return '确认完成后自动结算';return o.timeline.some(e=>e.label==='系统自动结算完成（模拟）')?'已自动结算':'自动结算处理中';}
const matchingPlayers=computed(()=>players.value.filter(p=>p.approved&&p.available&&p.userId!==selectedOrder.value?.bossId&&canServe(p,selectedOrder.value?.serviceType||'hourly',selectedOrder.value?.gameId||'')));
const gameBy=(id:string)=>games.value.find(g=>g.id===id);
const playerBusy=(id:string)=>orders.value.some(o=>orderMembers(o).some(m=>m.playerId===id)&&['accepted','serving','confirming'].includes(o.status)&&o.id!==selectedOrder.value?.id);
const formatDate=computed(()=>new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',month:'long',day:'numeric',weekday:'long'}).format(Date.now()));
const trendMax=computed(()=>Math.max(...(dashboard.value?.revenueTrend.map(d=>d.revenue)||[0]),10000));
const trendPoints=computed(()=>dashboard.value?.revenueTrend.map((d,i)=>`${55+i*90},${192-d.revenue/trendMax.value*150}`).join(' ')||'');
const chartArea=computed(()=>`M 55 200 L ${trendPoints.value.split(' ').join(' L ')} L 595 200 Z`);
const totalGameOrders=computed(()=>dashboard.value?.gameDistribution.reduce((n,g)=>n+g.orders,0)||0);
const ringStyle=computed(()=>{let start=0;const stops=dashboard.value?.gameDistribution.map(g=>{const end=start+g.orders/(totalGameOrders.value||1)*100;const v=`${g.color} ${start}% ${end}%`;start=end;return v;});return {background:`conic-gradient(${stops?.join(',')||'#eee 0% 100%'})`};});
watch([query,gameFilter,statusFilter,serviceFilter],()=>currentPage.value=1);
function navigate(id:string){mobileSidebarOpen.value=false;page.value=id;location.hash=id;query.value='';gameFilter.value='all';statusFilter.value='all';serviceFilter.value='all';customerFilter.value='all';currentPage.value=1;}
function onHash(){const raw=location.hash.slice(1)||'dashboard',id=legacyPages[raw]||raw;if(availableNav.value.some(n=>n.id===id)){if(id!==raw)navigate(id);else page.value=id;}else navigate('dashboard');}
async function load(silent=false){if(refreshing.value)return;refreshing.value=true;if(!silent)loading.value=true;try{if(!staff.session)await staff.login('admin');const [o,p,g,d,s,u,a]=await Promise.all([api.orders({scope:'all'}),api.players(),api.games(),api.dashboard(),api.settings(),api.users(),api.applications()]);orders.value=o;players.value=p;games.value=g;dashboard.value=d;settings.value=s;registeredUsers.value=u;applications.value=a;audit.value=isAdmin.value?await api.audit():[];if(selectedOrder.value)selectedOrder.value=orders.value.find(o=>o.id===selectedOrder.value?.id)||selectedOrder.value;loadError.value='';}catch(e){if(e instanceof ApiError&&e.code===401){await staff.login(staff.session?.role||'admin');refreshing.value=false;await load(silent);return;}loadError.value=e instanceof Error?e.message:'数据加载失败';}finally{loading.value=false;refreshing.value=false;}}
async function run(job:()=>Promise<void>){if(busy.value)return;busy.value=true;try{await job();}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(e instanceof Error?e.message:'操作失败');}finally{busy.value=false;}}
function openOrder(o:Order){selectedOrder.value=o;orderDrawer.value=true;}
function openAssign(o:Order){selectedOrder.value=o;assignPlayer.value='';assignReason.value='';assignDialog.value=true;}
async function submitAssign(){await run(async()=>{if(!assignPlayer.value){ElMessage.warning('请选择成员');return;}await api.act(selectedOrder.value!.id,'assign',{playerId:assignPlayer.value,reason:assignReason.value});assignDialog.value=false;await load(true);ElMessage.success('派单成功，两端订单已同步');});}
function openReview(o:Order,approve:boolean){selectedOrder.value=o;reviewApprove.value=approve;reviewNote.value='';refundDialog.value=true;}
async function submitReview(){await run(async()=>{await api.act(selectedOrder.value!.id,'review-refund',{approve:reviewApprove.value,note:reviewNote.value});refundDialog.value=false;await load(true);ElMessage.success(reviewApprove.value?'已模拟原路退款，报酬已调整':'已拒绝退款申请');});}
async function requestRefund(o:Order){await run(async()=>{const {value}=await ElMessageBox.prompt('请填写退款原因（至少 5 字），将发起全额退款申请交由财务审核。','客服发起售后',{inputType:'textarea',inputPlaceholder:'例如：客户申请取消，尚未开始服务',confirmButtonText:'提交申请',cancelButtonText:'取消',inputValidator:(v:string)=>v?.trim().length>=5||'请填写至少 5 字原因'});await api.act(o.id,'refund',{reason:value,amount:o.amount});await load(true);ElMessage.success('已提交退款申请');});}
async function cancelOrder(o:Order){await run(async()=>{await ElMessageBox.confirm('确认关闭这笔未支付订单？','取消订单',{confirmButtonText:'确认取消',cancelButtonText:'返回'});await api.act(o.id,'cancel');await load(true);ElMessage.success('订单已取消');});}
function editPlayer(p:Player){selectedPlayer.value=p;editPrice.value=p.price/100;playerDialog.value=true;}
async function savePlayer(){await run(async()=>{await api.updatePlayer(selectedPlayer.value!.id,{price:Math.round(editPrice.value*100)});playerDialog.value=false;await load(true);ElMessage.success('单价已更新，仅对新订单生效');});}
async function togglePlayer(p:Player){await run(async()=>{await api.updatePlayer(p.id,{available:!p.available});await load(true);ElMessage.success(p.available?'已暂停接单':'已开启接单');});}
function openApplication(a:Application,status:'assessment'|'approved'|'rejected'){selectedApplication.value=a;applicationAction.value=status;assessmentScore.value=80;assessmentNote.value='';applicationDialog.value=true;}
async function reviewApplication(){await run(async()=>{await api.reviewApplication(selectedApplication.value!.id,{status:applicationAction.value,score:applicationAction.value==='approved'?assessmentScore.value:undefined,note:assessmentNote.value});await load(true);applicationDialog.value=false;ElMessage.success('申请状态已更新');});}
async function switchRole(role:Role){await run(async()=>{await staff.login(role);roleDialog.value=false;if(!availableNav.value.some(n=>n.id===page.value))navigate('dashboard');await load(true);ElMessage.success(`已切换为${roleLabels[role]}，操作权限同步更新`);});}
function exportCsv(){
  let rows:(string|number)[][];
  rows=[['订单号','下单用户','游戏','区服','成员','服务类型','履约要求','金额（元）','状态','售后状态','创建时间'],...filteredOrders.value.map(o=>[o.id,o.bossName,o.gameName,o.region,orderMembers(o).map(m=>m.name).join('、')||'待接单',serviceLabels[o.serviceType],orderSummary(o),money(o.amount),statusLabels[o.status],o.refundStatus,time(o.createdAt)])];
  const escape=(v:string|number)=>{const text=String(v).replace(/^[=+\-@]/,"'$&");return '"'+text.replace(/"/g,'""')+'"';};
  const blob=new Blob(['\ufeff'+rows.map(row=>row.map(escape).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8;'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`${CLUB_NAME}-订单-${new Date().toISOString().slice(0,10)}.csv`;a.click();URL.revokeObjectURL(url);ElMessage.success('CSV 已导出');
}
function openMobile(){window.open(`${import.meta.env.BASE_URL}../mobile/#/pages/index/index`,'_blank');}
function doSearch(){navigate('orders');query.value=globalSearch.value;globalSearch.value='';}
onMounted(async()=>{sidebarViewport.addEventListener('change',onSidebarViewportChange);window.addEventListener('keydown',onSidebarKeydown);await load();if(!availableNav.value.some(n=>n.id===page.value))navigate('dashboard');if(location.hash.slice(1)!==page.value)navigate(page.value);refreshTimer=setInterval(()=>load(true),12000);window.addEventListener('hashchange',onHash);window.addEventListener('storage',onStorage);});
function onStorage(e:StorageEvent){if(e.key==='stellar-club:database:v1')load(true);}
onUnmounted(()=>{sidebarViewport.removeEventListener('change',onSidebarViewportChange);window.removeEventListener('keydown',onSidebarKeydown);clearInterval(refreshTimer);window.removeEventListener('hashchange',onHash);window.removeEventListener('storage',onStorage);});
</script>

<template>
  <div class="admin-app" :class="{'sidebar-collapsed':sidebarCollapsed}">
    <button v-if="mobileSidebarOpen" class="sidebar-backdrop" aria-label="关闭菜单遮罩" @click="mobileSidebarOpen=false"/>
    <aside id="admin-sidebar" class="sidebar" :class="{collapsed:sidebarCollapsed,open:mobileSidebarOpen}"><button class="sidebar-close" aria-label="关闭菜单" @click="mobileSidebarOpen=false"><el-icon><Close/></el-icon></button><div class="brand" :title="settings?.name||CLUB_NAME"><span class="brand-symbol">✳</span><div>{{settings?.name||CLUB_NAME}}<small>{{CLUB_NAME_EN}}</small></div></div><div class="workspace"><div class="workspace-icon">N</div><div><strong>俱乐部工作空间</strong><small>CLUB WORKSPACE</small></div><el-icon><ArrowDown/></el-icon></div><div class="nav-caption">运营管理 <span>WORKSPACE</span></div><nav><button v-for="n in availableNav" :key="n.id" :aria-label="n.label" :title="n.label" :class="{active:page===n.id}" @click="navigate(n.id)"><el-icon><component :is="n.icon"/></el-icon><span>{{n.label}}</span><span v-if="n.id==='orders'&&dashboard?.unassigned" class="nav-count">{{dashboard.unassigned}}</span><span v-if="n.id==='refunds'&&pendingRefunds.length" class="nav-count warning-count">{{pendingRefunds.length}}</span></button></nav><div class="sidebar-bottom"><div class="mobile-entry"><div class="entry-icon"><el-icon><Monitor/></el-icon></div><strong>移动端体验</strong><p>发布需求，协作接单。</p><button @click="openMobile">打开移动端 <el-icon><TopRight/></el-icon></button></div><button class="staff-card" aria-label="切换演示身份" title="切换演示身份" @click="roleDialog=true;mobileSidebarOpen=false"><div class="staff-avatar">{{staff.session?.name.slice(0,1)||'陈'}}</div><div><strong>{{staff.session?.name||'陈安'}}<span>{{staff.session?roleLabels[staff.session.role]:'管理员'}}</span></strong><small>切换演示身份</small></div><el-icon><Switch/></el-icon></button></div></aside>
    <div class="main-shell"><header class="top-header"><div class="breadcrumb"><button class="sidebar-toggle" :aria-label="sidebarToggleLabel" :title="sidebarToggleLabel" :aria-expanded="sidebarExpanded" aria-controls="admin-sidebar" @click="toggleSidebar"><el-icon><Expand v-if="isCompactViewport||sidebarCollapsed"/><Fold v-else/></el-icon></button><span>运营管理</span><el-icon><ArrowRight/></el-icon><strong>{{pageLabel}}</strong></div><div class="header-actions"><div class="global-search"><el-icon><Search/></el-icon><input v-model="globalSearch" placeholder="搜索订单号、客户或成员" @keyup.enter="doSearch"/><kbd>↵</kbd></div><span class="environment"><i/> 模拟环境</span><el-popover placement="bottom-end" :width="320" trigger="click"><template #reference><button class="notification-button" aria-label="查看待办提醒"><el-icon><Bell/></el-icon><i v-if="pendingRefunds.length"/></button></template><div class="notification-panel"><strong>待办提醒</strong><p>{{pendingRefunds.length}} 笔退款申请等待审核，{{dashboard?.unassigned||0}} 笔订单等待接单。</p><el-button size="small" @click="navigate('refunds')">查看退款售后</el-button><el-button size="small" @click="navigate('orders');statusFilter='waiting'">查看待派订单</el-button></div></el-popover><button class="header-avatar" @click="roleDialog=true">{{staff.session?.name.slice(0,1)||'陈'}}</button></div></header>
    <div class="demo-bar"><div><span class="demo-badge">DEMO</span> 演示模式：所有收付款均为模拟，数据仅保存在当前浏览器。</div><button @click="openMobile">打开 H5 联动体验 <el-icon><TopRight/></el-icon></button></div>
    <main class="main-content" v-loading="loading"><el-alert v-if="loadError" :title="loadError" type="error" show-icon :closable="false"><el-button link @click="load()">重新加载</el-button></el-alert>
      <div class="page-top"><div><div class="page-eyebrow">{{page==='dashboard'?'YOUR CLUB, AT A GLANCE':CLUB_NAME_EN+' / OPERATIONS'}}</div><h1>{{page==='dashboard'?'工作概览':pageLabel}}<span v-if="page==='dashboard'" class="greeting-sun">✳</span></h1><p>{{page==='dashboard'?`欢迎回来，${staff.session?.name||'陈安'}。这里是俱乐部今天的运营情况。`:({orders:'从下单到完成，让每一次服务都有迹可循。',players:'管理成员资料、接单状态和服务单价。',customers:'统一管理注册用户，查看消费记录、入驻申请与专项考核进展。',refunds:'审核退款申请，核实服务记录并更新订单。',audit:'重要操作完整留痕，让协作更透明。'} as Record<string,string>)[page]}}</p></div><div class="page-top-actions"><span v-if="page==='dashboard'" class="today-date"><el-icon><Clock/></el-icon>{{formatDate}}</span><el-button v-if="page==='orders'" :icon="Download" @click="exportCsv()">导出订单</el-button><el-button :icon="Refresh" :loading="refreshing" @click="load(true)">{{page==='dashboard'?'刷新数据':'刷新'}}</el-button></div></div>

      <template v-if="page==='dashboard' && dashboard">
        <div class="stats-grid"><div class="stat-card revenue-card"><div class="stat-head">今日实收（元）<div class="stat-icon green"><el-icon><CreditCard/></el-icon></div></div><div class="stat-value"><span>¥</span>{{compactMoney(dashboard.todayRevenue)}}</div><div class="stat-foot"><span class="stat-note">已扣除已完成退款</span><span class="tiny-chart">▁▂▁▃▂▅▄▆▅█</span></div></div><div class="stat-card"><div class="stat-head">今日新增订单<div class="stat-icon purple"><el-icon><Tickets/></el-icon></div></div><div class="stat-value">{{dashboard.todayOrders}}<small>笔</small></div><div class="stat-foot"><span class="stat-chip purple-chip">{{dashboard.liveOrders}} 笔服务流转中</span><button @click="navigate('orders')">查看订单 <el-icon><ArrowRight/></el-icon></button></div></div><div class="stat-card"><div class="stat-head">在线成员<div class="stat-icon blue"><el-icon><UserFilled/></el-icon></div></div><div class="stat-value">{{dashboard.onlinePlayers}}<small>/ {{dashboard.totalPlayers}} 人</small></div><div class="stat-foot"><span class="stat-chip green-chip"><i/> {{dashboard.availablePlayers}} 位可立即接单</span><button @click="navigate('players')"><el-icon><ArrowRight/></el-icon></button></div></div><div class="stat-card"><div class="stat-head">待处理售后<div class="stat-icon orange"><el-icon><Service/></el-icon></div></div><div class="stat-value">{{dashboard.refundPending}}<small>笔</small></div><div class="stat-foot"><span class="stat-note">及时回应，安心服务</span><button class="orange-link" @click="navigate('refunds')">去处理 <el-icon><ArrowRight/></el-icon></button></div></div></div>
        <div class="quick-actions"><button @click="navigate('orders');statusFilter='waiting'"><span class="quick-action-icon"><el-icon><Tickets/></el-icon></span><span>待分配订单<strong>{{dashboard.unassigned}} 笔</strong></span><el-icon><ArrowRight/></el-icon></button><button @click="navigate('refunds')"><span class="quick-action-icon purple-action"><el-icon><Service/></el-icon></span><span>待处理售后<strong>{{dashboard.refundPending}} 笔</strong></span><el-icon><ArrowRight/></el-icon></button><button @click="navigate('customers');customerFilter='onboarding'"><span class="quick-action-icon"><el-icon><User/></el-icon></span><span>入驻处理中<strong>{{pendingApplications.length}} 项申请</strong></span><el-icon><ArrowRight/></el-icon></button></div>
        <div class="dashboard-middle"><section class="panel revenue-panel"><div class="panel-heading"><div><h2>经营趋势 <span>REVENUE OVERVIEW</span></h2><p>最近 7 天订单净收款，按订单创建日归集</p></div><span class="date-range">最近 7 天</span></div><div class="chart-legend"><span><i class="legend-dot"/>订单净收款</span><strong>¥{{compactMoney(dashboard.revenueTrend.reduce((n,d)=>n+d.revenue,0))}}</strong><span class="legend-muted">合计</span></div><div class="line-chart"><svg viewBox="0 0 640 232" role="img" aria-label="最近七天订单净收款趋势"><defs><linearGradient id="areaFill" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stop-color="#8172de" stop-opacity=".23"/><stop offset="100%" stop-color="#8172de" stop-opacity=".01"/></linearGradient></defs><g v-for="i in 5" :key="i"><line x1="55" x2="610" :y1="200-(i-1)*40" :y2="200-(i-1)*40" stroke="#e9ebf0" stroke-dasharray="4 5"/><text x="0" :y="204-(i-1)*40" fill="#9b9eaa" font-size="10">{{compactMoney((i-1)*trendMax/4)}}</text></g><path :d="chartArea" fill="url(#areaFill)"/><polyline :points="trendPoints" fill="none" stroke="#8372df" stroke-width="2.8" stroke-linejoin="round" stroke-linecap="round"/><g v-for="(d,i) in dashboard.revenueTrend" :key="d.label"><circle :cx="55+i*90" :cy="192-d.revenue/trendMax*150" r="4" fill="#fff" stroke="#8372df" stroke-width="2"><title>{{d.label}}：¥{{money(d.revenue)}} / {{d.orders}} 笔</title></circle><text :x="55+i*90" y="226" text-anchor="middle" fill="#969aa7" font-size="10">{{d.label}}</text></g></svg></div></section><section class="panel distribution-panel"><div class="panel-heading"><div><h2>大家都在玩</h2><p>已付款订单的游戏分布</p></div><el-icon class="muted-icon"><TrendCharts/></el-icon></div><div class="donut-wrap"><div class="donut" :style="ringStyle"><div><strong>{{totalGameOrders}}</strong><span>已付款订单</span></div></div><span class="donut-decoration">✳</span></div><div class="game-legend"><div v-for="g in dashboard.gameDistribution" :key="g.name"><span class="legend-name"><i :style="{background:g.color}"/>{{g.name}}</span><strong>{{g.orders}} <small>笔</small></strong><span>{{Math.round(g.orders/(totalGameOrders||1)*100)}}%</span></div></div></section></div>
        <div class="dashboard-bottom"><section class="panel latest-panel"><div class="panel-heading"><div><h2>最新订单 <span class="count-soft">{{orders.length}}</span></h2><p>查看最新订单与处理进度</p></div><button class="panel-link" @click="navigate('orders')">全部订单 <el-icon><ArrowRight/></el-icon></button></div><el-table :data="dashboard.recentOrders" class="clean-table" @row-click="openOrder"><el-table-column label="订单 / 游戏" min-width="180"><template #default="{row}"><div class="table-game"><div class="game-tile" :style="{background:gameBy(row.gameId)?.color+'19',color:gameBy(row.gameId)?.color}">{{gameBy(row.gameId)?.short}}</div><div><strong>{{row.gameName}}</strong><small>{{row.id}}</small></div></div></template></el-table-column><el-table-column label="下单用户 / 成员" min-width="130"><template #default="{row}"><span class="table-person">{{row.bossName}}<span class="person-divider">/</span>{{row.playerName||'待接单'}}</span></template></el-table-column><el-table-column label="金额" width="92"><template #default="{row}"><strong class="table-money">¥{{money(row.amount)}}</strong></template></el-table-column><el-table-column label="状态" width="112"><template #default="{row}"><span class="status-badge" :class="row.refundStatus==='pending'?'refund':row.status"><i/>{{row.refundStatus==='pending'?'售后处理中':statusLabels[row.status as keyof typeof statusLabels]}}</span></template></el-table-column><el-table-column label="" width="45"><template #default><el-icon class="muted-icon"><ArrowRight/></el-icon></template></el-table-column></el-table></section><section class="panel activity-panel"><div class="panel-heading"><div><h2>工作动态</h2><p>团队协作，实时留痕</p></div><el-icon class="muted-icon"><Clock/></el-icon></div><div class="activity-list"><div v-for="(a,i) in dashboard.activity.slice(0,4)" :key="a.id" class="activity-item"><div class="activity-dot" :class="'dot-'+i"><el-icon><component :is="i===0?Service:i===1?Select:i===2?User:Check"/></el-icon></div><div><strong>{{a.actor}} <span>{{a.action}}</span></strong><p>{{a.detail}}</p><small>{{time(a.at)}}</small></div></div><div v-if="!dashboard.activity.length" class="blank-text">暂时没有操作记录</div></div></section></div>
        <div class="dashboard-footer"><span><i/> 数据来自当前浏览器的模拟服务</span><span>{{CLUB_NAME}} · 俱乐部工作台<span class="footer-star">✳</span></span></div>
      </template>

      <template v-else-if="page==='orders'">
        <div class="summary-strip"><div><span>全部订单</span><strong>{{orders.length}}</strong></div><div><span>待接单</span><strong class="purple-text">{{orders.filter(o=>o.status==='waiting').length}}</strong></div><div><span>服务流转中</span><strong>{{orders.filter(o=>['accepted','serving','confirming'].includes(o.status)).length}}</strong></div><div><span>已完成</span><strong>{{orders.filter(o=>o.status==='completed').length}}</strong></div></div>
        <section class="panel order-panel"><div class="table-tabs"><button v-for="f in [{id:'all',label:'全部订单'},...Object.entries(statusLabels).map(([id,label])=>({id,label}))]" :key="f.id" :class="{active:statusFilter===f.id}" @click="statusFilter=f.id">{{f.label}}<span>{{f.id==='all'?orders.length:orders.filter(o=>o.status===f.id).length}}</span></button></div><div class="table-toolbar"><el-input v-model="query" :prefix-icon="Search" placeholder="搜索订单号、下单用户、成员" clearable class="search-input"/><el-select v-model="serviceFilter" class="game-select" aria-label="订单类型" v-if="page==='orders'"><el-option label="全部类型" value="all"/><el-option label="护航订单" value="escort"/><el-option label="组队订单" value="hourly"/></el-select><el-select v-model="gameFilter" class="game-select"><el-option label="全部游戏" value="all"/><el-option v-for="g in games" :key="g.id" :label="g.name" :value="g.id"/></el-select><span class="result-count">共 {{filteredOrders.length}} 笔订单</span><el-button text :icon="Refresh" @click="query='';gameFilter='all';statusFilter='all';serviceFilter='all'">重置筛选</el-button></div><el-table :data="pagedOrders" empty-text="没有匹配的订单，请调整筛选条件"><el-table-column label="订单 / 创建时间" min-width="190"><template #default="{row}"><button class="order-id-link" @click="openOrder(row)">{{row.id}}</button><div class="cell-sub">{{time(row.createdAt)}}</div></template></el-table-column><el-table-column label="游戏 / 区服" min-width="160"><template #default="{row}"><div class="table-game"><div class="game-tile small-tile" :style="{background:gameBy(row.gameId)?.color+'19',color:gameBy(row.gameId)?.color}">{{gameBy(row.gameId)?.short}}</div><div><strong>{{row.gameName}}</strong><small>{{row.region}} · {{serviceLabels[row.serviceType as keyof typeof serviceLabels]}}</small></div></div></template></el-table-column><el-table-column label="下单用户" min-width="90" prop="bossName"/><el-table-column label="成员" min-width="90"><template #default="{row}"><span :class="{'cell-muted':!row.playerName}">{{row.playerName||'待接单'}}</span></template></el-table-column><el-table-column label="金额" width="100"><template #default="{row}"><strong class="table-money">¥{{money(row.amount)}}</strong></template></el-table-column><el-table-column label="状态" width="118"><template #default="{row}"><span class="status-badge" :class="row.status"><i/>{{statusLabels[row.status as keyof typeof statusLabels]}}</span><div v-if="row.refundStatus==='pending'" class="refund-hint">售后处理中</div></template></el-table-column><el-table-column label="操作" min-width="150" fixed="right"><template #default="{row}"><el-button link type="primary" @click="openOrder(row)">详情</el-button><el-button v-if="canDispatch&&['waiting','accepted'].includes(row.status)&&row.refundStatus!=='pending'" link type="primary" @click="openAssign(row)">{{row.playerId?'改派':'派单'}}</el-button><el-button v-if="canDispatch&&row.status==='unpaid'" link @click="cancelOrder(row)">取消</el-button></template></el-table-column></el-table><div class="table-pagination"><span>显示第 {{filteredOrders.length?((currentPage-1)*pageSize+1):0}}～{{Math.min(currentPage*pageSize,filteredOrders.length)}} 条，共 {{filteredOrders.length}} 条</span><el-pagination v-model:current-page="currentPage" :page-size="pageSize" :total="filteredOrders.length" layout="prev, pager, next" background/></div></section>
      </template>

      <template v-else-if="page==='players'"><div class="summary-strip"><div><span>认证成员</span><strong>{{players.filter(p=>p.approved).length}}</strong></div><div><span>组队资格</span><strong>{{players.filter(p=>p.approved&&p.qualifications.includes('hourly')).length}}</strong></div><div><span>护航资格</span><strong>{{players.filter(p=>p.approved&&p.qualifications.includes('escort')).length}}</strong></div><div><span>可接单状态</span><strong class="purple-text">{{onlinePlayers.length}}</strong></div></div><section class="panel"><div class="table-tabs"><button v-for="f in [{id:'all',label:'全部成员'},{id:'online',label:'可接单'},{id:'rest',label:'休息中'}]" :key="f.id" :class="{active:playerFilter===f.id}" @click="playerFilter=f.id">{{f.label}}</button></div><div class="table-toolbar"><el-input v-model="query" :prefix-icon="Search" clearable placeholder="搜索昵称、技能或标签" class="search-input"/><el-select v-model="gameFilter" class="game-select"><el-option label="全部游戏" value="all"/><el-option v-for="g in games" :key="g.id" :label="g.name" :value="g.id"/></el-select><span class="result-count">共 {{filteredPlayers.length}} 位成员</span></div><el-table :data="filteredPlayers" empty-text="没有匹配的成员"><el-table-column label="成员" min-width="170"><template #default="{row}"><div class="table-game"><div class="player-avatar" :style="{background:row.color}">{{row.avatar}}</div><div><strong>{{row.name}}</strong><small>{{row.id.toUpperCase()}} · {{row.approved?'认证成员':'资格未开通'}}</small></div></div></template></el-table-column><el-table-column label="擅长游戏" min-width="160"><template #default="{row}"><div class="game-tags"><span v-for="id in row.gameIds" :key="id">{{gameBy(id)?.name}}</span></div></template></el-table-column><el-table-column label="接单资格" min-width="145"><template #default="{row}"><div class="game-tags"><span v-for="type in row.qualifications" :key="type">{{serviceLabels[type as keyof typeof serviceLabels]}}</span><span v-if="!row.qualifications.length">未开通</span></div></template></el-table-column><el-table-column label="时薪" width="100"><template #default="{row}">¥{{money(row.price)}}</template></el-table-column><el-table-column label="评分 / 历史订单" min-width="130"><template #default="{row}"><span class="rating-star">★</span> {{row.rating}}<div class="cell-sub">历史 {{row.completed}} 单</div></template></el-table-column><el-table-column label="接单状态" width="110"><template #default="{row}"><span class="status-badge" :class="!row.approved?'unpaid':row.available?'completed':'cancelled'"><i/>{{!row.approved?'未认证':row.available?'可接单':'休息中'}}</span></template></el-table-column><el-table-column label="操作" min-width="180"><template #default="{row}"><template v-if="isAdmin"><el-button link type="primary" :disabled="busy" @click="togglePlayer(row)">{{row.available?'暂停接单':'开启接单'}}</el-button><el-button link @click="editPlayer(row)">调整单价</el-button></template><span v-else class="cell-muted">只读查看</span></template></el-table-column></el-table><div class="panel-footnote">历史评分与订单数为档案样例；订单和报酬数据由模拟接口实时计算。修改单价不影响已创建订单。</div></section></template>

      <template v-else-if="page==='customers'">
        <div class="summary-strip"><div><span>注册用户</span><strong>{{allCustomers.length}}</strong></div><div><span>资料待审核</span><strong class="orange-text">{{applications.filter(a=>a.status==='pending').length}}</strong></div><div><span>专项考核中</span><strong class="purple-text">{{applications.filter(a=>a.status==='assessment').length}}</strong></div><div><span>已取得接单资格</span><strong>{{allCustomers.filter(c=>c.qualifications.length).length}}</strong></div></div>
        <section class="panel">
          <div class="table-tabs"><button v-for="f in [{id:'all',label:'全部用户'},{id:'onboarding',label:'入驻处理中'},{id:'qualified',label:'已有资格'},{id:'ordinary',label:'普通用户'}]" :key="f.id" :class="{active:customerFilter===f.id}" @click="customerFilter=f.id">{{f.label}}</button></div>
          <div class="table-toolbar"><el-input v-model="query" :prefix-icon="Search" class="search-input" clearable placeholder="搜索用户昵称或编号"/><span class="result-count">共 {{customers.length}} 位用户</span></div>
          <el-table :data="customers" empty-text="没有找到匹配的用户">
            <el-table-column label="用户" min-width="170"><template #default="{row}"><div class="table-game"><div class="customer-avatar">{{row.name.slice(0,1)}}</div><div><strong>{{row.name}}</strong><small>{{row.id}}</small></div></div></template></el-table-column>
            <el-table-column label="接单资格" min-width="140"><template #default="{row}"><div class="game-tags"><span v-for="type in row.qualifications" :key="type">{{type==='escort'?'护航':'组队'}}</span><span v-if="!row.qualifications.length" class="cell-muted">普通用户</span></div></template></el-table-column>
            <el-table-column label="入驻情况" min-width="140"><template #default="{row}"><div v-for="a in row.applications.filter((a:Application)=>['pending','assessment'].includes(a.status))" :key="a.id" class="cell-sub onboarding-status">{{a.serviceType==='escort'?'护航':'组队'}} · {{applicationLabels[a.status as Application['status']]}}</div><span v-if="!row.onboarding" class="cell-muted">{{row.applications.length?'申请已处理':'暂无进行中的申请'}}</span></template></el-table-column>
            <el-table-column label="累计订单" prop="count" width="95"/>
            <el-table-column label="累计净支付" min-width="120"><template #default="{row}"><strong>¥{{money(row.total)}}</strong></template></el-table-column>
            <el-table-column label="最近下单" min-width="150"><template #default="{row}">{{row.last?time(row.last):'尚未下单'}}</template></el-table-column>
            <el-table-column label="操作" min-width="215" fixed="right"><template #default="{row}"><el-button link type="primary" @click="customerId=row.id;customerDrawer=true">查看订单</el-button><el-button v-if="row.applications.length" link type="primary" @click="openProgress(row.id)">{{row.onboarding?'查看入驻进展':'入驻记录'}}</el-button></template></el-table-column>
          </el-table>
          <div class="panel-footnote">注册用户统一展示，未下单也可查看。组队和护航分别申请、分别考核；从用户行查看进展并处理对应申请。</div>
        </section>
      </template>

      <template v-else-if="page==='refunds'"><div class="summary-strip"><div><span>待审核退款</span><strong class="orange-text">{{pendingRefunds.length}}</strong></div><div><span>待审核金额</span><strong>¥{{money(pendingRefunds.reduce((n,o)=>n+(o.refundAmount||0),0))}}</strong></div><div><span>已模拟退款</span><strong>{{orders.filter(o=>o.refundStatus==='refunded').length}} <small>笔</small></strong></div><div><span>已退款金额</span><strong>¥{{money(orders.filter(o=>o.refundStatus==='refunded').reduce((n,o)=>n+(o.refundAmount||0),0))}}</strong></div></div><section class="panel"><div class="table-tabs"><button v-for="f in [{id:'pending',label:'待审核'},{id:'refunded',label:'已退款'},{id:'rejected',label:'未通过'},{id:'all',label:'全部售后'}]" :key="f.id" :class="{active:refundFilter===f.id}" @click="refundFilter=f.id">{{f.label}}</button></div><div class="table-toolbar"><el-input v-model="query" :prefix-icon="Search" class="search-input" clearable placeholder="搜索订单、下单用户或成员"/><span class="result-count">{{canFinance?'你可以审核并模拟退款':'当前为客服视角，可查看售后，财务或管理员可审核'}}</span></div><el-table :data="filteredRefunds" empty-text="当前没有这类售后申请"><el-table-column label="关联订单" min-width="185"><template #default="{row}"><button class="order-id-link" @click="openOrder(row)">{{row.id}}</button><div class="cell-sub">{{row.gameName}} · {{row.bossName}}</div></template></el-table-column><el-table-column label="申请金额" width="120"><template #default="{row}"><strong class="orange-text">¥{{money(row.refundAmount||0)}}</strong><div class="cell-sub">实付 ¥{{money(row.amount)}}</div></template></el-table-column><el-table-column label="退款原因" min-width="240"><template #default="{row}"><div class="reason-cell">{{row.refundReason}}</div><div v-if="row.refundReviewNote" class="cell-sub">审核：{{row.refundReviewNote}}</div></template></el-table-column><el-table-column label="状态" width="120"><template #default="{row}"><span class="status-badge" :class="row.refundStatus==='pending'?'unpaid':row.refundStatus==='refunded'?'completed':'cancelled'"><i/>{{row.refundStatus==='pending'?'待审核':row.refundStatus==='refunded'?'已模拟退款':'未通过'}}</span></template></el-table-column><el-table-column label="操作" min-width="160"><template #default="{row}"><template v-if="row.refundStatus==='pending'&&canFinance"><el-button link type="primary" @click="openReview(row,true)">同意退款</el-button><el-button link type="danger" @click="openReview(row,false)">拒绝</el-button></template><el-button v-else link type="primary" @click="openOrder(row)">查看详情</el-button></template></el-table-column></el-table><div class="panel-footnote">退款均为模拟原路退回。待审核订单暂停履约及结算；部分退款通过后会按原订单抽成规则重新计算报酬。</div></section></template>

      <template v-else-if="page==='audit'"><section class="panel"><div class="panel-heading"><div><h2>操作记录</h2><p>订单、派单、入驻审核、退款和自动结算均保留操作记录。</p></div><span class="count-soft">{{audit.length}} 条</span></div><el-table :data="audit" empty-text="暂无操作日志"><el-table-column label="操作时间" min-width="150"><template #default="{row}">{{time(row.at)}}</template></el-table-column><el-table-column label="操作人" prop="actor" min-width="130"/><el-table-column label="动作" min-width="130"><template #default="{row}"><span class="audit-action">{{row.action}}</span></template></el-table-column><el-table-column label="关联对象" prop="target" min-width="220"/><el-table-column label="说明" prop="detail" min-width="280"/></el-table><div class="panel-footnote">演示环境最多保留最近 300 条操作记录。生产环境应由服务端持久化并控制审计访问权限。</div></section></template>
    </main>
    </div>

    <el-drawer v-model="orderDrawer" title="订单详情" size="500px" class="order-drawer"><template v-if="selectedOrder"><div class="drawer-status"><span class="status-badge" :class="selectedOrder.status"><i/>{{statusLabels[selectedOrder.status]}}</span><span v-if="selectedOrder.refundStatus==='pending'" class="status-badge refund">售后处理中</span><h2>{{selectedOrder.gameName}} · {{serviceLabels[selectedOrder.serviceType]}}</h2><p>{{selectedOrder.id}}</p></div><div class="drawer-note"><strong>{{selectedOrder.serviceType==='escort'?'任务项':'服务时长'}}</strong><p>{{orderSummary(selectedOrder)}}</p></div><div class="drawer-note"><strong>{{selectedOrder.productId?'来源商品':'服务需求'}}</strong><p>{{selectedOrder.productTitle||'快速邀请'}} · {{selectedOrder.preferredPlayerId?'指定成员':'公共单'}}</p></div><div class="drawer-amount"><span>订单金额</span><strong>¥{{money(selectedOrder.amount)}}</strong></div><div class="detail-grid"><div><span>下单用户</span><strong>{{selectedOrder.bossName}}</strong></div><div><span>服务成员</span><strong>{{selectedOrder.playerName||selectedOrder.preferredPlayerName||'等待接单'}}</strong></div><div><span>游戏区服</span><strong>{{selectedOrder.region}}</strong></div><div><span>下单时间</span><strong>{{time(selectedOrder.createdAt)}}</strong></div><div><span>服务费比例</span><strong>{{selectedOrder.commissionBps/100}}%</strong></div><div><span>成员净报酬</span><strong>¥{{money(selectedOrder.earnings)}}</strong></div></div><div v-if="selectedOrder.note" class="drawer-note"><strong>下单用户备注</strong><p>{{selectedOrder.note}}</p></div><div v-if="selectedOrder.refundStatus!=='none'" class="drawer-refund"><strong>售后申请 · {{selectedOrder.refundStatus==='pending'?'待审核':selectedOrder.refundStatus==='refunded'?'已模拟退款':'未通过'}}</strong><p>申请 ¥{{money(selectedOrder.refundAmount||0)}} · {{selectedOrder.refundReason}}</p><p v-if="selectedOrder.refundReviewNote">审核：{{selectedOrder.refundReviewNote}}</p></div><div v-if="orderMembers(selectedOrder).length" class="drawer-note"><strong>协作成员与净报酬分配</strong><div v-for="(m,i) in orderMembers(selectedOrder)" :key="m.playerId" class="allocation-row"><span>{{m.name}} · {{i===0?'负责人':'副手'}}</span><strong>¥{{money(participantEarnings(selectedOrder,m.playerId))}}</strong><small>{{settlementLabel(selectedOrder)}}</small></div><p>用户确认完成后自动结算；待审核售后暂停结算。净报酬按人数均分，尾差按成员顺序补齐。</p></div><div class="drawer-section-title">订单动态</div><el-timeline><el-timeline-item v-for="(e,i) in selectedOrder.timeline" :key="i" :timestamp="time(e.at)+' · '+e.actor" :color="i===selectedOrder.timeline.length-1?'#8d7adf':'#d6d3e4'"><strong>{{e.label}}</strong><p v-if="e.note" class="timeline-note">{{e.note}}</p></el-timeline-item></el-timeline><div class="drawer-actions"><el-button v-if="canDispatch&&['waiting','accepted'].includes(selectedOrder.status)&&selectedOrder.refundStatus!=='pending'" type="primary" @click="openAssign(selectedOrder)">{{selectedOrder.playerId?'改派成员':'分配成员'}}</el-button><el-button v-if="canDispatch&&selectedOrder.paidAt&&!selectedOrder.settlementId&&['none','rejected'].includes(selectedOrder.refundStatus)&&selectedOrder.status!=='cancelled'" @click="requestRefund(selectedOrder)">发起退款申请</el-button><template v-if="canFinance&&selectedOrder.refundStatus==='pending'"><el-button type="primary" @click="openReview(selectedOrder,true)">同意退款</el-button><el-button @click="openReview(selectedOrder,false)">拒绝退款</el-button></template><el-button v-if="canDispatch&&selectedOrder.status==='unpaid'" @click="cancelOrder(selectedOrder)">取消未支付订单</el-button></div></template></el-drawer>
    <el-drawer v-model="progressDrawer" :title="(progressUser?.name||'用户')+' · 入驻进展'" size="680px" class="onboarding-drawer">
      <p class="dialog-description">组队与护航资格独立审核、考核，通过后仅开通申请游戏的商品发布与接单资格。</p>
      <section v-for="a in progressUser?.applications||[]" :key="a.id" class="onboarding-card">
        <div class="onboarding-card-heading"><h3>{{a.serviceType==='escort'?'护航资格':'组队资格'}}</h3><span class="status-badge" :class="a.status==='approved'?'completed':a.status==='rejected'?'cancelled':'unpaid'">{{applicationLabels[a.status]}}</span></div>
        <div class="onboarding-flow">提交申请 <el-icon><ArrowRight/></el-icon> 资料审核 <el-icon><ArrowRight/></el-icon> 专项考核</div>
        <dl class="onboarding-details"><div><dt>申请游戏</dt><dd>{{a.gameIds.map(id=>gameBy(id)?.name||id).join('、')}}</dd></div><div><dt>申请时间</dt><dd>{{time(a.createdAt)}}</dd></div><div><dt>经验与说明</dt><dd>{{a.introduction}}</dd></div><div v-if="a.reviewNote"><dt>最新反馈</dt><dd>{{a.reviewNote}}</dd></div><div v-if="a.score!==undefined"><dt>考核成绩</dt><dd>{{a.score}} 分</dd></div><div v-if="a.reviewedAt"><dt>处理时间</dt><dd>{{time(a.reviewedAt)}}</dd></div></dl>
        <div v-if="isAdmin&&['pending','assessment'].includes(a.status)" class="onboarding-actions"><el-button v-if="a.status==='pending'" type="primary" :disabled="busy" @click="openApplication(a,'assessment')">审核资料并安排考核</el-button><el-button v-if="a.status==='assessment'" type="primary" :disabled="busy" @click="openApplication(a,'approved')">录入成绩并通过</el-button><el-button type="danger" plain :disabled="busy" @click="openApplication(a,'rejected')">不通过</el-button></div>
        <p v-else-if="['pending','assessment'].includes(a.status)" class="cell-sub">当前身份仅可查看进展，管理员可处理申请。</p>
      </section>
      <el-empty v-if="!progressUser?.applications.length" description="暂无入驻申请"/>
    </el-drawer>
    <el-dialog v-model="applicationDialog" :title="applicationAction==='assessment'?'资料审核与考核安排':applicationAction==='approved'?'录入专项考核结果':'申请不通过'" width="500px"><p class="dialog-description">{{selectedApplication?.name}} · {{selectedApplication?serviceLabels[selectedApplication.serviceType]:''}}</p><el-form label-position="top"><el-form-item v-if="applicationAction==='approved'" label="考核成绩（60 分及以上通过）"><el-input-number v-model="assessmentScore" :min="0" :max="100" :precision="0"/></el-form-item><el-form-item :label="applicationAction==='assessment'?'审核说明与考核安排':'考核依据或未通过原因'" required><el-input v-model="assessmentNote" type="textarea" :rows="4" :maxlength="500" placeholder="请填写具体说明，将同步显示给申请人。"/></el-form-item></el-form><template #footer><el-button @click="applicationDialog=false">取消</el-button><el-button type="primary" :loading="busy" @click="reviewApplication">确认提交</el-button></template></el-dialog>
    <el-dialog v-model="assignDialog" :title="selectedOrder?.playerId?'改派服务成员':'为订单分配成员'" width="480px"><div class="dialog-order-summary"><span>{{selectedOrder?.gameName}} · {{selectedOrder?.region}}</span><strong>{{selectedOrder?.id}}</strong></div><el-form label-position="top"><el-form-item label="选择成员"><el-select v-model="assignPlayer" placeholder="选择支持该游戏且有空闲容量的成员" class="full-width"><el-option v-for="p in matchingPlayers" :key="p.id" :label="`${p.name} · ${p.subtitle}${playerBusy(p.id)?'（已有未完成订单）':''}`" :value="p.id" :disabled="playerBusy(p.id)"/></el-select></el-form-item><el-form-item label="派单备注（选填）"><el-input v-model="assignReason" type="textarea" :rows="3" :maxlength="200" placeholder="说明派单或改派原因，记录会显示在订单动态中。"/></el-form-item></el-form><template #footer><el-button @click="assignDialog=false">取消</el-button><el-button type="primary" :loading="busy" @click="submitAssign">确认派单</el-button></template></el-dialog>
    <el-dialog v-model="refundDialog" :title="reviewApprove?'审核并模拟退款':'拒绝退款申请'" width="470px"><div class="refund-dialog-amount"><span>申请退款金额</span><strong>¥{{money(selectedOrder?.refundAmount||0)}}</strong><p>{{selectedOrder?.refundReason}}</p></div><el-alert v-if="reviewApprove" title="确认后立即模拟原路退款，不会发生真实资金变动。" type="info" :closable="false" show-icon/><el-form label-position="top"><el-form-item label="审核说明" required><el-input v-model="reviewNote" type="textarea" :rows="3" :maxlength="200" placeholder="请填写至少 2 字的审核依据，下单用户可在订单详情查看。"/></el-form-item></el-form><template #footer><el-button @click="refundDialog=false">返回</el-button><el-button :type="reviewApprove?'primary':'danger'" :loading="busy" @click="submitReview">{{reviewApprove?'确认模拟退款':'确认拒绝'}}</el-button></template></el-dialog>
    <el-dialog v-model="playerDialog" title="调整成员服务单价" width="420px"><p class="dialog-description">{{selectedPlayer?.name}} · {{selectedPlayer?.subtitle}}</p><el-form label-position="top"><el-form-item label="服务单价（元 / 小时）"><el-input-number v-model="editPrice" :min="1" :max="1000" :precision="2"/></el-form-item></el-form><el-alert title="只对新订单生效，历史订单价格与报酬不变。" :closable="false" type="info"/><template #footer><el-button @click="playerDialog=false">取消</el-button><el-button type="primary" :loading="busy" @click="savePlayer">保存单价</el-button></template></el-dialog>
    <el-dialog v-model="roleDialog" title="切换员工演示身份" width="480px"><p class="dialog-description">不同身份会限制页面和接口操作权限。登录均为模拟。</p><button v-for="r in [{role:'admin',name:'陈安',label:'管理员',detail:'用户与成员管理、入驻考核及操作日志'},{role:'customer_service',name:'许知',label:'客服',detail:'查询订单、派单、发起售后申请'},{role:'finance',name:'沈禾',label:'财务',detail:'审核退款、查看订单与自动结算结果'}]" :key="r.role" class="staff-role-option" :class="{selected:staff.session?.role===r.role}" :disabled="busy" @click="switchRole(r.role as Role)"><span class="staff-avatar">{{r.name.slice(0,1)}}</span><span><strong>{{r.name}} · {{r.label}}</strong><small>{{r.detail}}</small></span><el-icon><component :is="staff.session?.role===r.role?CircleCheck:ArrowRight"/></el-icon></button></el-dialog>
    <el-drawer v-model="customerDrawer" :title="selectedCustomer?.name+'的订单'" size="600px"><div class="customer-drawer-summary"><div>累计订单<strong>{{selectedCustomer?.count}}</strong></div><div>累计净支付<strong>¥{{money(selectedCustomer?.total||0)}}</strong></div></div><el-table :data="customerOrders"><el-table-column label="订单" min-width="190"><template #default="{row}"><button class="order-id-link" @click="openOrder(row)">{{row.id}}</button><div class="cell-sub">{{row.gameName}} · {{statusLabels[row.status as keyof typeof statusLabels]}}</div></template></el-table-column><el-table-column label="金额" width="110"><template #default="{row}">¥{{money(row.amount)}}</template></el-table-column><el-table-column label="下单时间" min-width="150"><template #default="{row}">{{time(row.createdAt)}}</template></el-table-column></el-table></el-drawer>
  </div>
</template>
